(* [comment removed for export] *)
Definition dof_WX (lo : Z) (sp : word) (P E ff fp : Z) : list (Z * Z) :=
  dof_W lo sp P E ++ [(as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 256); (sh ff, sh ff + 32)]%Z.

(* [comment removed for export] *)
Definition dof_lay (sp : word) (spa : Z) (gsz : nat) : Prop :=
  spa + 184 + Z.of_nat gsz = bv_unsigned sp + -104 /\ bv_unsigned sp + -304 <= spa /\ spa mod 32 = 0.

(* [comment removed for export] *)
Definition dof_sav (s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra : word) : list cell :=
  [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

(* [comment removed for export] *)
Definition dof_ctx (LF : list fframe) (m m1 : mem) (sp : word) (spa : Z) (gsz : nat) (gj : list byte)
    (rav s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word)
    (P E vp : Z) (vbs : list byte) (c1 : pcore) (pad7 pad2 : list byte) (ecs : list cell) (g : bool)
    (lo shi ff fp : Z) (h0 h1 h2 h3 : word) (shb : list byte) : Prop :=
  rw_cells asegs m1 (spa + 184) [CB gsz gj]
  /\ rw_cells asegs m1 (bv_unsigned sp + -104) (dof_sav s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav)
  /\ rw_cells asegs m1 ff [C8 h0; C8 h1; C8 h2; C8 h3]
  /\ rw_cells asegs m1 (ff + 248) [C8 (wz fp)]
  /\ rw_cells asegs m1 (Z.shiftr ff 3 + 2147450880) [CB 32 shb]
  /\ rw_cells asegs m1 fp [C1 (b8 1)]
  /\ rw_cells asegs m1 P (ParserCoreCells c1 pad7 pad2)
  /\ rw_cells asegs m1 E ecs
  /\ bytes_at asegs m1 vp vbs
  /\ AHttpCat m1 g
  /\ stk asegs m1 lo spa
  /\ munch (dof_WX lo sp P E ff fp) m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1
  /\ dof_side H LF m m1 lo shi ff fp P E vp (Z.of_nat (length vbs))
  /\ bv_unsigned rav mod 2 = 0.

(* [comment removed for export] *)
Definition dof_bpure (sp : word) (spa : Z) (gsz : nat) (P E lo shi : Z) (c : pcore) (fld vp : Z) (vbs : list byte) : Prop :=
  dof_pure sp P E lo shi c fld vp vbs /\ dof_lay sp spa gsz /\ Z.of_nat (length vbs) + vp < 2^64.


(* [comment removed for export] *)
Definition dof_arm_stmt (pc : Z) : Prop :=
  forall (ra sp gp tp : word) (s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s3x t3 t4 t5 t6 : word)
    (LF : list fframe) (m m1 : mem) (spa : Z) (gsz : nat) (gj js fj : list byte)
    (P E vp fld lo shi ff fp : Z) (vbs : list byte) (c : pcore) (pad7 pad2 : list byte) (E0 : ecv) (g : bool) (h0 h1 h2 h3 : word),
  dof_ctx LF m m1 sp spa gsz gj ra s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v P E vp vbs c pad7 pad2 (ErrCodeCells E0) g lo shi ff fp h0 h1 h2 h3 DOF_SH0 ->
  ec_ok E0 -> dof_bpure sp spa gsz P E lo shi c fld vp vbs ->
  rw_cells asegs m1 spa [CB 184 js] -> rw_cells asegs m1 (ff + 32) [CB 216 fj] ->
  evt asegs (dof_post H ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc LF P E lo shi c pad7 pad2 vp vbs m)
    (MS (mkR rax (wz spa) gp tp t0 t1 t2 sp (wz spa) a0 a1 a2 a3 a4 a5 a6 a7
             (wz ff) s3x (wz P) (wz fld) (wz vp) (wz (Z.of_nat (length vbs))) (wz (Z.shiftr ff 3 + 2147450880)) (wz E) (wz ASHADOW_BASE) (wz ff) t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom asegs)).
