Definition dof_exitP_stmt (pc : Z) : Prop :=
  forall (ra sp gp tp : word) (s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s3x s4x s5x s6x s7x s9x s10x t3 t4 t5 t6 : word)
    (LF : list fframe) (m mx : mem) (spa : Z) (gsz : nat) (gj : list byte) (cs : list cell) (shb : list byte)
    (P E vp fld lo shi ff fp : Z) (vbs : list byte) (c c' : pcore) (pad7 pad2 : list byte) (E' : ecv) (g' : bool)
    (h0 h1 h2 h3 : word) (bflag : byte),
  rw_cells asegs mx spa cs -> Z.of_nat (cells_size cs) = 184 ->
  rw_cells asegs mx (spa + 184) [CB gsz gj] ->
  rw_cells asegs mx (bv_unsigned sp + -104) (dof_sav s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) ->
  rw_cells asegs mx ff [C8 h0; C8 h1; C8 h2; C8 h3] -> rw_cells asegs mx (ff + 248) [C8 (wz fp)] ->
  rw_cells asegs mx (Z.shiftr ff 3 + 2147450880) [CB 32 shb] ->
  rw_cells asegs mx fp [C1 bflag] ->
  stk asegs mx lo spa -> mem_inv asegs mx ->
  dof_side H LF m mx lo shi ff fp P E vp (Z.of_nat (length vbs)) ->
  munch (dof_WX H lo sp P E ff fp) m mx -> wmono asegs m mx ->
  rw_cells asegs mx P (ParserCoreCells c' pad7 pad2) -> dof_core c c' ->
  rw_cells asegs mx E (ErrCodeCells E') -> dof_out E' ->
  bytes_at asegs mx vp vbs -> AHttpCat mx g' ->
  dof_bpure sp spa gsz P E lo shi c fld vp vbs -> bv_unsigned ra mod 2 = 0 ->
  evt asegs (dof_post H ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc LF P E lo shi c pad7 pad2 vp vbs m)
    (MS (mkR rax (wz spa) gp tp t0 t1 t2 sp (wz spa) a0 a1 a2 a3 a4 a5 a6 a7
             (wz ff) s3x s4x s5x s6x s7x (wz (Z.shiftr ff 3 + 2147450880)) s9x s10x (wz ff) t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None mx (seg_rom asegs)).

Local Ltac exitP_script HH JMP :=
  intros ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s3x s4x s5x s6x s7x s9x s10x t3 t4 t5 t6
         LF m mx spa gsz gj cs shb P E vp fld lo shi ff fp vbs c c' pad7 pad2 E' g' h0 h1 h2 h3 bflag;
